INSERT INTO public."Products" ("Id", "Name", "Brand", "Quantity", "Date_Import", "OldPrice", "Price", "Sold", "CategoryId", "Description", "ImageUrl") VALUES (1, 'Office 365 Chính Hãng', 'Microsoft', 12, '2026-03-28 00:00:00+07', 10000, 5000, 0, 2, '<div id="seofy_dbl_69c1a69d79e11" class="seofy_module_double_headings acenter " bis_skin_checked="1" style="vertical-align: baseline; font-family: Quicksand; font-size: 18px; outline: 0px; padding: 0px; margin: 0px; border: 0px; text-align: center; color: rgb(30, 30, 30);"><div class="heading_title" bis_skin_checked="1" style="vertical-align: baseline; font-family: inherit; font-weight: 800; font-style: inherit; font-size: 36px; outline: 0px; padding: 23px 0px 0px; margin: 10px 0px 0px; border: 0px; position: relative; z-index: 1; color: rgb(0, 0, 0); line-height: 1.333;"><div class="heading_title_mobile" bis_skin_checked="1" style="vertical-align: baseline; font-family: inherit; font-weight: inherit; font-style: inherit; font-size: 23px; outline: 0px; padding: 0px; margin: 0px; border: 0px; line-height: 1.333; color: inherit;"><div bis_skin_checked="1" style="vertical-align: baseline; font-family: inherit; font-weight: inherit; font-style: inherit; font-size: inherit; outline: 0px; padding: 0px; margin: 0px; border: 0px; line-height: inherit; color: inherit;"><span style="font-family: &quot;Segoe UI&quot;;">ĐẶC ĐIỂM CỦA TÀI KHOẢN OFFICE 365 CHÍNH HÃNG CHẤT LƯỢNG</span></div></div></div></div><div class="wpb_text_column wpb_content_element  vc_custom_1630148275179" bis_skin_checked="1" style="vertical-align: baseline; font-family: Quicksand; font-size: 18px; outline: 0px; padding: 0px; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; border: 0px; color: rgb(30, 30, 30); margin-top: 50px !important;"><div class="wpb_wrapper" bis_skin_checked="1" style="vertical-align: baseline; font-family: inherit; font-weight: inherit; font-style: inherit; outline: 0px; padding: 0px; margin: 0px; border: 0px;"><ul class="seofy_check seofy_check_gradient" style="vertical-align: baseline; font-family: inherit; font-weight: inherit; font-style: inherit; outline: 0px; padding: 0px 0px 20px; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; border: 0px;"><li aria-level="1" style="vertical-align: baseline; font-family: inherit; font-style: inherit; outline: 0px; padding: 0px 0px 0px 54px; margin: 0px 0px 16px; border: 0px; position: relative; z-index: 1; list-style: none; line-height: 30px;"><span style="vertical-align: baseline; font-family: inherit; font-weight: inherit; font-style: inherit; outline: 0px; padding: 0px; margin: 0px; border: 0px; color: rgb(255, 0, 0);"><span style="vertical-align: baseline; font-family: &quot;Segoe UI&quot;; font-weight: 700; font-style: inherit; outline: 0px; padding: 0px; margin: 0px; border: 0px; color: rgb(0, 0, 0);">Office 365 bản mới nhất 2021 dạng tài khoản bản quyền trọn đời. (Ngoài ra nếu bạn không muốn dùng tài khoản Office 365 có sẵn, chúng tôi còn cung cấp Key Office 365 Personal)</span></span></li><li aria-level="1" style="vertical-align: baseline; font-family: inherit; font-style: inherit; outline: 0px; padding: 0px 0px 0px 54px; margin: 0px 0px 16px; border: 0px; position: relative; z-index: 1; list-style: none; line-height: 30px;"><span style="font-family: &quot;Segoe UI&quot;;">Sử dụng tối đa trên 5 thiết bị cùng 1 thời điểm</span></li><li aria-level="1" style="vertical-align: baseline; font-family: inherit; font-style: inherit; outline: 0px; padding: 0px 0px 0px 54px; margin: 0px 0px 16px; border: 0px; position: relative; z-index: 1; list-style: none; line-height: 30px;"><span style="font-family: &quot;Segoe UI&quot;;">Office 365 tương thích với các thiết bị từ Window, MAC, Smartphone,…</span></li><li aria-level="1" style="vertical-align: baseline; font-family: inherit; font-style: inherit; outline: 0px; padding: 0px 0px 0px 54px; margin: 0px 0px 16px; border: 0px; position: relative; z-index: 1; list-style: none; line-height: 30px;"><span style="font-family: &quot;Segoe UI&quot;;">Giúp nâng cao hiệu quả sử dụng: Người dùng có thể làm việc từ mọi nơi, làm việc online và offline.</span></li><li aria-level="1" style="vertical-align: baseline; font-family: inherit; font-style: inherit; outline: 0px; padding: 0px 0px 0px 54px; margin: 0px 0px 16px; border: 0px; position: relative; z-index: 1; list-style: none; line-height: 30px;"><span style="font-family: &quot;Segoe UI&quot;;">Giao diện trực quan, dễ dàng sử dụng.</span></li><li aria-level="1" style="vertical-align: baseline; font-family: inherit; font-style: inherit; outline: 0px; padding: 0px 0px 0px 54px; margin: 0px 0px 16px; border: 0px; position: relative; z-index: 1; list-style: none; line-height: 30px;"><span style="font-family: &quot;Segoe UI&quot;;">Làm việc nhóm dễ dàng hơn với Microsoft Team.</span></li><li aria-level="1" style="vertical-align: baseline; font-family: inherit; font-style: inherit; outline: 0px; padding: 0px 0px 0px 54px; margin: 0px 0px 16px; border: 0px; position: relative; z-index: 1; list-style: none; line-height: 30px;"><span style="font-family: &quot;Segoe UI&quot;;">Luôn cập nhật và tiếp cận những ứng dụng và tính năng mới nhất.</span></li><li aria-level="1" style="vertical-align: baseline; font-family: inherit; font-style: inherit; outline: 0px; padding: 0px 0px 0px 54px; margin: 0px 0px 16px; border: 0px; position: relative; z-index: 1; list-style: none; line-height: 30px;"><span style="font-family: &quot;Segoe UI&quot;;">Khả năng bảo mật cao và độ tin cậy mạnh mẽ.</span></li><li aria-level="1" style="vertical-align: baseline; font-family: inherit; font-weight: inherit; font-style: inherit; outline: 0px; padding: 0px 0px 0px 54px; margin: 0px; border: 0px; position: relative; z-index: 1; list-style: none; line-height: 30px;"><span style="font-family: &quot;Segoe UI&quot;;">Hỗ trợ tất cả các ngôn ngữ trên toàn cầu như Tiếng Việt, Anh, Đức, Pháp, Tây Ban Nha, Nhật Bản, Hàn Quốc, Ý, Ba Lan, Hà Lan, Do Thái, Bồ Đào Nha, Ả Rập,…</span></li><li aria-level="1" style="vertical-align: baseline; font-family: inherit; font-weight: inherit; font-style: inherit; outline: 0px; padding: 0px 0px 0px 54px; margin: 0px; border: 0px; position: relative; z-index: 1; list-style: none; line-height: 30px;"><span style="font-family: &quot;Segoe UI&quot;;"><div id="seofy_dbl_69c1a69d7c792" class="seofy_module_double_headings acenter " bis_skin_checked="1" style="vertical-align: baseline; font-family: Quicksand; outline: 0px; padding: 0px; margin: 0px; border: 0px; text-align: center;"><div class="heading_title" bis_skin_checked="1" style="vertical-align: baseline; font-family: inherit; font-weight: 800; font-style: inherit; font-size: 36px; outline: 0px; padding: 23px 0px 0px; margin: 10px 0px 0px; border: 0px; position: relative; z-index: 1; color: rgb(0, 0, 0); line-height: 1.333;"><div class="heading_title_mobile" bis_skin_checked="1" style="vertical-align: baseline; font-family: inherit; font-weight: inherit; font-style: inherit; font-size: 28px; outline: 0px; padding: 0px; margin: 0px; border: 0px; line-height: 1.333; color: inherit;"><div bis_skin_checked="1" style="vertical-align: baseline; font-family: inherit; font-weight: inherit; font-style: inherit; font-size: inherit; outline: 0px; padding: 0px; margin: 0px; border: 0px; line-height: inherit; color: inherit;">Hướng dẫn cài đặt Office 365 chi tiết và đầy đủ nhất</div></div></div></div><div class="wpb_text_column wpb_content_element " bis_skin_checked="1" style="vertical-align: baseline; font-family: Quicksand; outline: 0px; padding: 0px; margin: 0px; border: 0px;"><div class="wpb_wrapper" bis_skin_checked="1" style="vertical-align: baseline; font-family: inherit; font-weight: inherit; font-style: inherit; outline: 0px; padding: 0px; margin: 0px; border: 0px;"><p style="vertical-align: baseline; font-family: inherit; font-weight: inherit; font-style: inherit; outline: 0px; padding: 0px; margin-right: 0px; margin-bottom: 18px; margin-left: 0px; border: 0px; text-align: center;"><span style="vertical-align: baseline; font-family: inherit; font-weight: 700; font-style: inherit; outline: 0px; padding: 0px; margin: 0px; border: 0px; color: rgb(0, 0, 0);">Bước 1</span>: Đăng nhập để tải xuống Office<br style="margin-bottom: 0px;">Truy nhập www.office.com và đăng nhập tài khoản Office 365 (Tài khoản bạn vừa mua).</p><p style="vertical-align: baseline; font-family: inherit; font-weight: inherit; font-style: inherit; outline: 0px; padding: 0px; margin-right: 0px; margin-bottom: 18px; margin-left: 0px; border: 0px; text-align: center;"><img src="https://res.cloudinary.com/dfskird4e/image/upload/v1774693975/products/hwxc3knltjq6o9lfqwau.png"></p><p style="vertical-align: baseline; outline: 0px; padding: 0px; margin-right: 0px; margin-bottom: 18px; margin-left: 0px; border: 0px; text-align: center;">Nhập mật khẩu của bạn và sau đó nhấp vào phần “Đăng nhập”.</p><p style="vertical-align: baseline; outline: 0px; padding: 0px; margin-right: 0px; margin-bottom: 18px; margin-left: 0px; border: 0px; text-align: center;"><br><span style="vertical-align: baseline; font-family: inherit; font-weight: 700; font-style: inherit; outline: 0px; padding: 0px; margin: 0px; border: 0px; color: rgb(0, 0, 0);">Bước 2:</span>&nbsp;Từ trang chủ của Office, chọn Cài đặt Office.</p><p style="vertical-align: baseline; outline: 0px; padding: 0px; margin-right: 0px; margin-bottom: 18px; margin-left: 0px; border: 0px; text-align: center;"><img src="https://res.cloudinary.com/dfskird4e/image/upload/v1774694064/products/vbjh1vplhurtugk3s5ad.png"><br><span style="vertical-align: baseline; font-family: inherit; font-weight: 700; font-style: inherit; outline: 0px; padding: 0px; margin: 0px; border: 0px; color: rgb(0, 0, 0);">Bước 3:</span>&nbsp;Cài đặt</p><ul style="vertical-align: baseline; outline: 0px; padding: 0px 0px 20px; margin-right: 0px; margin-left: 0px; border: 0px; text-align: center;"><li style="vertical-align: baseline; font-family: inherit; font-weight: inherit; font-style: inherit; outline: 0px; padding: 0px 0px 0px 20px; margin: 0px; border: 0px; position: relative; z-index: 1; list-style: none; line-height: 30px;">Vào thư mục lưu file vừa tải về, click chuột phải và chọn “Run as administrator”</li><li style="vertical-align: baseline; font-family: inherit; font-weight: inherit; font-style: inherit; outline: 0px; padding: 0px 0px 0px 20px; margin: 0px; border: 0px; position: relative; z-index: 1; list-style: none; line-height: 30px;"><img src="https://res.cloudinary.com/dfskird4e/image/upload/v1774694089/products/wft3vkf6aha7ff2qpcoo.png"><br></li></ul><p style="vertical-align: baseline; outline: 0px; padding: 0px; margin-right: 0px; margin-bottom: 18px; margin-left: 0px; border: 0px; text-align: center;"></p><p style="vertical-align: baseline; outline: 0px; padding: 0px; margin-right: 0px; margin-bottom: 18px; margin-left: 0px; border: 0px; text-align: center;">Chờ đợi quá trình cài đặt hoàn tất.</p><p style="vertical-align: baseline; outline: 0px; padding: 0px; margin-right: 0px; margin-bottom: 18px; margin-left: 0px; border: 0px; text-align: center;"><img src="https://res.cloudinary.com/dfskird4e/image/upload/v1774694109/products/l2q4hewxdrdgltm2lyku.png"><br></p><p style="vertical-align: baseline; outline: 0px; padding: 0px; margin-right: 0px; margin-bottom: 18px; margin-left: 0px; border: 0px; text-align: center;"></p><p style="vertical-align: baseline; outline: 0px; padding: 0px; margin-right: 0px; margin-bottom: 18px; margin-left: 0px; border: 0px; text-align: center;">Sau khi cài đặt xong, bạn chọn ” Đóng”</p><p style="vertical-align: baseline; outline: 0px; padding: 0px; margin-right: 0px; margin-bottom: 18px; margin-left: 0px; border: 0px; text-align: center;"><br><span style="vertical-align: baseline; font-family: inherit; font-weight: 700; font-style: inherit; outline: 0px; padding: 0px; margin: 0px; border: 0px; color: rgb(0, 0, 0);">Bước 4:</span>&nbsp;Sau khi quá trình cài đặt hoàn tất bạn vào ô tìm kiếm, tìm kiếm một ứng dụng của Office 365, ví dụ “Word”.</p><p style="vertical-align: baseline; outline: 0px; padding: 0px; margin-right: 0px; margin-bottom: 18px; margin-left: 0px; border: 0px; text-align: center;"><img src="https://res.cloudinary.com/dfskird4e/image/upload/v1774694132/products/enzlmq38i7jetpyxqmea.png"><br></p><p style="vertical-align: baseline; outline: 0px; padding: 0px; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; border: 0px; text-align: center;">Vào tài khoản để xem lại thông tin, như vậy bạn đã cài bản quyền Office 365 hoàn tất.</p></div></div></span></li></ul></div></div>', '858a08a1322549cfaaee3f9f3f9881e5_20260328103611.jpg');
INSERT INTO public."Products" ("Id", "Name", "Brand", "Quantity", "Date_Import", "OldPrice", "Price", "Sold", "CategoryId", "Description", "ImageUrl") VALUES (2, 'ChatGPT Plus', 'OpenAI', 17, '2026-03-28 00:00:00+07', 23700, 7900, 0, 3, '<h3 style="vertical-align: baseline; font-family: Quicksand; font-weight: 700; font-size: 24px; outline: 0px; padding: 0px; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; border: 0px; color: rgb(0, 0, 0); line-height: 36px;"><span style="vertical-align: baseline; font-family: &quot;Segoe UI&quot;; font-style: inherit; outline: 0px; padding: 0px; margin: 0px; border: 0px;">I. ChatGPT Plus Là Gì?</span></h3><p style="vertical-align: baseline; font-family: Quicksand; font-size: 18px; outline: 0px; padding: 0px; margin-right: 0px; margin-bottom: 18px; margin-left: 0px; border: 0px; color: rgb(30, 30, 30);"><span style="vertical-align: baseline; font-family: &quot;Segoe UI&quot;; font-weight: 700; font-style: inherit; outline: 0px; padding: 0px; margin: 0px; border: 0px; color: rgb(0, 0, 0);">ChatGPT Plus</span><span style="font-family: &quot;Segoe UI&quot;;">&nbsp;là phiên bản&nbsp;</span><span style="vertical-align: baseline; font-family: &quot;Segoe UI&quot;; font-weight: 700; font-style: inherit; outline: 0px; padding: 0px; margin: 0px; border: 0px; color: rgb(0, 0, 0);">cao cấp trả phí</span><span style="font-family: &quot;Segoe UI&quot;;">&nbsp;của&nbsp;</span><span style="vertical-align: baseline; font-family: &quot;Segoe UI&quot;; font-weight: 700; font-style: inherit; outline: 0px; padding: 0px; margin: 0px; border: 0px; color: rgb(0, 0, 0);">ChatGPT</span><span style="font-family: &quot;Segoe UI&quot;;">, một sản phẩm tiên tiến được phát triển bởi&nbsp;</span><span style="vertical-align: baseline; font-family: &quot;Segoe UI&quot;; font-weight: 700; font-style: inherit; outline: 0px; padding: 0px; margin: 0px; border: 0px; color: rgb(0, 0, 0);">OpenAI</span><span style="font-family: &quot;Segoe UI&quot;;">&nbsp;và chính thức ra mắt vào tháng 2 năm 2023. Với khả năng vượt trội và trải nghiệm ưu việt,&nbsp;</span><span style="vertical-align: baseline; font-family: &quot;Segoe UI&quot;; font-weight: 700; font-style: inherit; outline: 0px; padding: 0px; margin: 0px; border: 0px; color: rgb(0, 0, 0);">ChatGPT Plus</span><span style="font-family: &quot;Segoe UI&quot;;">&nbsp;là giải pháp hoàn hảo cho những ai muốn tối ưu hóa công việc, học tập và sáng tạo.</span></p><p style="vertical-align: baseline; font-family: Quicksand; font-size: 18px; outline: 0px; padding: 0px; margin-right: 0px; margin-bottom: 18px; margin-left: 0px; border: 0px; color: rgb(30, 30, 30);"><span style="font-family: &quot;Segoe UI&quot;;">Sử dụng&nbsp;</span><span style="vertical-align: baseline; font-family: &quot;Segoe UI&quot;; font-weight: 700; font-style: inherit; outline: 0px; padding: 0px; margin: 0px; border: 0px; color: rgb(0, 0, 0);">mô hình GPT-4</span><span style="font-family: &quot;Segoe UI&quot;;">, ChatGPT Plus cung cấp khả năng xử lý tốt hơn, tốc độ nhanh hơn và nhiều tính năng mới so với phiên bản miễn phí dựa trên GPT-3.5. Đặc biệt, OpenAI vẫn duy trì phiên bản miễn phí để phục vụ đa dạng nhu cầu người dùng, nhưng nếu bạn cần một công cụ mạnh mẽ hơn,&nbsp;</span><span style="vertical-align: baseline; font-family: &quot;Segoe UI&quot;; font-weight: 700; font-style: inherit; outline: 0px; padding: 0px; margin: 0px; border: 0px; color: rgb(0, 0, 0);">ChatGPT Plus</span><span style="font-family: &quot;Segoe UI&quot;;">&nbsp;là lựa chọn lý tưởng.</span></p><h3 style="vertical-align: baseline; font-family: Quicksand; font-weight: 700; font-size: 24px; outline: 0px; padding: 0px; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; border: 0px; color: rgb(0, 0, 0); line-height: 36px;"><span style="vertical-align: baseline; font-family: &quot;Segoe UI&quot;; font-style: inherit; outline: 0px; padding: 0px; margin: 0px; border: 0px;">II. Chức Năng Nổi Bật Của ChatGPT Plus – Tài Khoản Dùng Chung</spa