span style="font-family: &quot;Segoe UI&quot;;">: Đội ngũ hỗ trợ tận tình, sẵn sàng giải đáp mọi thắc mắc của bạn bất cứ lúc nào.</span></li></ul><p style="vertical-align: baseline; font-family: Quicksand; font-size: 18px; outline: 0px; padding: 0px; margin-right: 0px; margin-bottom: 18px; margin-left: 0px; border: 0px; color: rgb(30, 30, 30);"><span style="vertical-align: baseline; font-family: &quot;Segoe UI&quot;; font-weight: 700; font-style: inherit; outline: 0px; padding: 0px; margin: 0px; border: 0px; color: rgb(0, 0, 0);">Avast SecureLine VPN 1 Thiết Bị – 3 Năm</span><span style="font-family: &quot;Segoe UI&quot;;">&nbsp;là lựa chọn hoàn hảo cho những ai cần một giải pháp bảo mật toàn diện và tiện lợi để bảo vệ thông tin cá nhân và quyền riêng tư của mình khi trực tuyến.</span></p>', '3b4bf2a3c4a5444fa74e3027381e91a1_20260328143005.jpg');
INSERT INTO public."Products" ("Id", "Name", "Brand", "Quantity", "Date_Import", "OldPrice", "Price", "Sold", "CategoryId", "Description", "ImageUrl") VALUES (8, 'Visio Professional 2024 – Theo Tài Khoản', 'Microsoft', 12, '2026-03-28 00:00:00+07', 27000, 9000, 0, 6, '<h3 style="vertical-align: baseline; font-family: Quicksand; font-weight: 700; font-size: 24px; outline: 0px; padding: 0px; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; border: 0px; color: rgb(0, 0, 0); line-height: 36px;"><span style="font-family: &quot;Segoe UI&quot;;">Giới thiệu&nbsp;</span><span data-sheets-root="1" style="vertical-align: baseline; font-style: inherit; outline: 0px; padding: 0px; margin: 0px; border: 0px; line-height: 36px; font-family: &quot;Segoe UI&quot;;">Visio Professional 2024</span></h3><p style="vertical-align: baseline; font-family: Quicksand; font-size: 18px; outline: 0px; padding: 0px; margin-right: 0px; margin-bottom: 18px; margin-left: 0px; border: 0px; color: rgb(30, 30, 30);"><span style="vertical-align: baseline; font-family: &quot;Segoe UI&quot;; font-weight: 700; font-style: inherit; outline: 0px; padding: 0px; margin: 0px; border: 0px; color: rgb(0, 0, 0);">Visio Professional 2024</span><span style="font-family: &quot;Segoe UI&quot;;">&nbsp;là công cụ hàng đầu dành cho việc tạo các sơ đồ chuyên nghiệp, giúp bạn trực quan hóa dữ liệu và thông tin phức tạp một cách hiệu quả. Đây là phiên bản mới nhất trong dòng sản phẩm Microsoft Visio, được thiết kế để hỗ trợ người dùng trong các lĩnh vực kỹ thuật, quản lý dự án, CNTT, và nhiều ngành nghề khác cần xây dựng sơ đồ một cách chi tiết và chính xác.</span></p><h3 style="vertical-align: baseline; font-family: Quicksand; font-weight: 700; font-size: 24px; outline: 0px; padding: 0px; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; border: 0px; color: rgb(0, 0, 0); line-height: 36px;"><span style="vertical-align: baseline; font-family: &quot;Segoe UI&quot;; font-style: inherit; outline: 0px; padding: 0px; margin: 0px; border: 0px;">Có gì mới trong Visio 2024?</span></h3><p style="vertical-align: baseline; font-family: Quicksand; font-size: 18px; outline: 0px; padding: 0px; margin-right: 0px; margin-bottom: 18px; margin-left: 0px; border: 0px; color: rgb(30, 30, 30);"><span style="vertical-align: baseline; font-family: &quot;Segoe UI&quot;; font-weight: 700; font-style: inherit; outline: 0px; padding: 0px; margin: 0px; border: 0px; color: rgb(0, 0, 0);">Visio 2024</span><span style="font-family: &quot;Segoe UI&quot;;">&nbsp;được thiết kế để giúp các cá nhân và nhóm dễ dàng tạo, chia sẻ và làm việc với các sơ đồ chuyên nghiệp hơn, đồng thời đơn giản hóa thông tin phức tạp. Phiên bản mới nhất này mang lại một loạt cải tiến về hình ảnh, công cụ tìm kiếm, giao diện và nội dung, nâng tầm trải nghiệm người dùng. Dưới đây là những tính năng mới và nổi bật của Visio 2024:</span></p><h4 style="vertical-align: baseline; font-family: Quicksand; font-weight: 700; font-size: 20px; outline: 0px; padding: 0px; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; border: 0px; color: rgb(0, 0, 0); line-height: 36px;"><span style="font-family: &quot;Segoe UI&quot;;">1.&nbsp;</span><span style="vertical-align: baseline; font-family: &quot;Segoe UI&quot;; font-style: inherit; outline: 0px; padding: 0px; margin: 0px; border: 0px;">Hình, mẫu tô và mẫu mới</span></h4><p style="vertical-align: baseline; font-family: Quicksand; font-size: 18px; outline: 0px; padding: 0px; margin-right: 0px; margin-bottom: 18px; margin-left: 0px; border: 0px; color: rgb(30, 30, 30);"><span style="font-family: &quot;Segoe UI&quot;;">Visio 2024 đã bổ sung thêm nhiều&nbsp;</span><span style="vertical-align: baseline; font-family: &quot;Segoe UI&quot;; font-weight: 700; font-style: inherit; outline: 0px; padding: 0px; margin: 0px; border: 0px; color: rgb(0, 0, 0);">hình, mẫu tô và mẫu</span><span style="font-family: &quot;Segoe UI&quot;;">&nbsp;mới để hỗ trợ việc tạo sơ đồ nhanh chóng và trực quan hơn:</spa