INSERT INTO public."Products" ("Id", "Name", "Brand", "Quantity", "Date_Import", "OldPrice", "Price", "Sold", "CategoryId", "Description", "ImageUrl") VALUES (10, 'Office 2021 Home & Business Cho Mac – Active Trên tài Khoản Cá Nhân', 'Microsoft', 4, '2026-03-28 00:00:00+07', 42000, 21000, 0, 2, '<h3 style="vertical-align: baseline; font-family: Quicksand; font-weight: 700; font-size: 24px; outline: 0px; padding: 0px; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; border: 0px; color: rgb(0, 0, 0); line-height: 36px;"><span style="font-family: &quot;Segoe UI&quot;;">Office 2021 Home &amp; Business Cho Mac – Active Trên tài Khoản Cá Nhân</span></h3><p style="vertical-align: baseline; font-family: Quicksand; font-size: 18px; outline: 0px; padding: 0px; margin-right: 0px; margin-bottom: 18px; margin-left: 0px; border: 0px; color: rgb(30, 30, 30);"><span style="font-family: &quot;Segoe UI&quot;;">Chắc hẵn rằng không còn ai trong chúng ta còn xa lạ với MS Office và đặc biệt với các chức năng và công dụng của nó mang lại là không thể phủ nhận được. Nhận thấy được tầm quan trọng đó Các phiên bản MS Office luôn phát triển để cải thiện các phiên bản phần mềm để phục vụ khách hàng một cách tận tình nhất. Rất nhiều các phiên bản Office đươc tung ra nhằm phục vụ mục đích của nhiều tổ chức từ các công ty cho đến trường học và người dùng cá nhân. Một số khách hàng không khỏi băn khoăn khi lựa chọn phiên bản phù hợp với nhu cầu sử dụng của mình. Tại truongshop.id.vn chúng tôi mang lại đầy đủ các phiên bản Office cho bạn và chỉ cần liên hệ để được hỗ trợ tư vấn theo nhu cầu của chính bạn.</span></p><p style="vertical-align: baseline; font-family: Quicksand; font-size: 18px; outline: 0px; padding: 0px; margin-right: 0px; margin-bottom: 18px; margin-left: 0px; border: 0px; color: rgb(30, 30, 30);"><span style="font-family: &quot;Segoe UI&quot;;">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</span><img src="https://res.cloudinary.com/dfskird4e/image/upload/v1774709209/products/ouxnskbugsgflpg1alor.png"></p><div id="attachment_6696" class="wp-caption aligncenter" bis_skin_checked="1" style="vertical-align: baseline; font-family: Quicksand; font-style: italic; font-size: 18px; outline: 0px; padding: 0px; margin: 0px auto; border: 0px; clear: both; max-width: 100%; color: rgb(30, 30, 30); width: 710px;"><p id="caption-attachment-6696" class="wp-caption-text" style="vertical-align: baseline; font-family: inherit; font-weight: inherit; font-style: inherit; outline: 0px; padding: 0px; margin: 0.5em 0px; border: 0px;"><span style="font-family: &quot;Segoe UI&quot;;">Office 2021 Home &amp; Business Cho Mac – Active Trên tài Khoản Cá Nhân</span></p></div><p style="vertical-align: baseline; font-family: Quicksand; font-size: 18px; outline: 0px; padding: 0px; margin-right: 0px; margin-bottom: 18px; margin-left: 0px; border: 0px; color: rgb(30, 30, 30);"><span style="font-family: &quot;Segoe UI&quot;;">Keyoff giới thiệu cho bạn sản phẩm Office 2021 Home &amp; Bussiness một phiên bản Office mới được ra mắt vào ngày 05/10/2021. Office 2021 mang lại các tính năng mới và được tối ưu và cải thiện các tính năng ở các phiên bản trước đó, Gói Office 2021 Home &amp; Business bao gồm các tính năng như:&nbsp;</span><em style="vertical-align: baseline; font-family: inherit; font-weight: inherit; outline: 0px; padding: 0px; margin: 0px; border: 0px;"><span style="font-family: &quot;Segoe UI&quot;;">Word, Excel, Powerpoint, Access, Outlook, Onenote&nbsp;</span></em><span style="font-family: &quot;Segoe UI&quot;;">với các tính năng mà phiên bản này mang lại thì hầu như Office 2021 Home &amp; Business phục vụ hầu hết các nhu cầu về từ học tập cho đến công việc văn phòng và kinh doanh. Một điều đặc biệt là bạn có thể đăng ký gói Officce 2021 Home &amp; Business được phát hành dành riêng cho Mac và đăng ký giấy phép trên chính tài khoản cá nhân và chỉ cần thanh toán một lần duy nhất. Giấy phép sẽ được gắn kèm trên tài khoản cá nhân của người dùng. Điều này mang lại tính linh động cao khi người dùng có thể chuyển đổi thiết bị sử dụng chỉ bằng cách đăng nhập tài khoản cá nhân. Phiên bản đăng ký sẽ được tải trực tiếp ngay từ trang thông tin cá nhân của bạn . Thực sự với cách thức đăng ký bản quyền như vậy Office 2021 Home &amp; Business mang lại rất nhiều sụ tiện lợi cho người dùng vừa tiết kiệm chi phí khi chỉ cần mua một lần duy nhất và có thể tải xuống phần mềm và chuyển đổi thiết bị chỉ bằng cách đăng nhập tài khoản cá nhân.</span></p><p style="vertical-align: baseline; font-family: Quicksand; font-size: 18px; outline: 0px; padding: 0px; margin-right: 0px; margin-bottom: 18px; margin-left: 0px; border: 0px; color: rgb(30, 30, 30);"><span style="font-family: &quot;Segoe UI&quot;;">&nbsp;</span></p><h3 style="vertical-align: baseline; font-family: Quicksand; font-weight: 700; font-size: 24px; outline: 0px; padding: 0px; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; border: 0px; color: rgb(0, 0, 0); line-height: 36px;"><span style="font-family: &quot;Segoe UI&quot;;">Office 2021 Home &amp; Business đăng ký trên tài khoản cá nhân là gì?</span></h3><p style="vertical-align: baseline; font-family: Quicksand; font-size: 18px; outline: 0px; padding: 0px; margin-right: 0px; margin-bottom: 18px; margin-left: 0px; border: 0px; color: rgb(30, 30, 30);"><span style="font-family: &quot;Segoe UI&quot;;">Gói đăng ký liên kết với tài khoản cá nhân của bạn có nghĩa là giấy phép phần mềm sẽ được gán trên tài khoản cá nhân của bạn. Bạn không cần phải nhập key trên phần mềm mà thay vào đó là đăng nhập để có bản quyền dùng phần mềm.</span></p><ul style="vertical-align: baseline; font-family: Quicksand; font-size: 18px; outline: 0px; padding: 0px 0px 20px; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; border: 0px; color: rgb(30, 30, 30);"><li style="vertical-align: baseline; font-family: inherit; font-weight: inherit; font-style: inherit; outline: 0px; padding: 0px 0px 0px 20px; margin: 0px 0px 10px; border: 0px; position: relative; z-index: 1; list-style: none; line-height: 30px;"><span style="font-family: &quot;Segoe UI&quot;;">Phần mềm sẽ được tải trực tiếp từ trang cá nhân của bạn.</span></li><li style="vertical-align: baseline; font-family: inherit; font-weight: inherit; font-style: inherit; outline: 0px; padding: 0px 0px 0px 20px; margin: 0px 0px 10px; border: 0px; position: relative; z-index: 1; list-style: none; line-height: 30px;"><span style="font-family: &quot;Segoe UI&quot;;">Có thể chuyển thiết bị để sử dụng.</span></li><li style="vertical-align: baseline; font-family: inherit; font-weight: inherit; font-style: inherit; outline: 0px; padding: 0px 0px 0px 20px; margin: 0px 0px 10px; border: 0px; position: relative; z-index: 1; list-style: none; line-height: 30px;"><span style="font-family: &quot;Segoe UI&quot;;">Cài lại máy hoặc phần mềm sẽ không mất bản quyền.</span></li><li style="vertical-align: baseline; font-family: inherit; font-weight: inherit; font-style: inherit; outline: 0px; padding: 0px 0px 0px 20px; margin: 0px 0px 10px; border: 0px; position: relative; z-index: 1; list-style: none; line-height: 30px;"><span style="font-family: &quot;Segoe UI&quot;;">Liên hệ </span><a href="https://truongshop.id.vn" target="_blank"><span style="font-family: &quot;Segoe UI&quot;;">TruongShop</span></a><span style="font-family: &quot;Segoe UI&quot;;">&nbsp;để biết thêm về thông tin sản phẩm</span></li></ul><h3 style="vertical-align: baseline; font-family: Quicksand; font-weight: 700; font-size: 24px; outline: 0px; padding: 0px; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; border: 0px; color: rgb(0, 0, 0); line-height: 36px;"><span style="font-family: &quot;Segoe UI&quot;;">Office 2021 Home &amp; Business Có Gì Mới??</span></h3><p style="vertical-align: baseline; font-family: Quicksand; font-size: 18px; outline: 0px; padding: 0px; margin-right: 0px; margin-bottom: 18px; margin-left: 0px; border: 0px; color: rgb(30, 30, 30);"><span style="font-family: &quot;Segoe UI&quot;;">Trong Office 2021, bạn sẽ có các tính năng đồng tác giả mới, công cụ viết mực, kiểu dữ liệu, chức năng, công cụ dịch và chỉnh sửa, đồ họa chuyển động, các tính năng dễ sử dụng, v.v.</span></p><p style="vertical-align: baseline; font-family: Quicksand; font-size: 18px; outline: 0px; padding: 0px; margin-right: 0px; margin-bottom: 18px; margin-left: 0px; border: 0px; color: rgb(30, 30, 30);"><span style="font-family: &quot;Segoe UI&quot;;">Cùng khám phá một số tính năng mới quan trọng trong Office 2021 Home &amp; Business:</span></p><h4 style="vertical-align: baseline; font-family: Quicksand; font-weight: 700; font-size: 20px; outline: 0px; padding: 0px; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; border: 0px; color: rgb(0, 0, 0); line-height: 36px;"><span style="font-family: &quot;Segoe UI&quot;;">Đồng tác giả (Co-author documents):&nbsp;</span><em style="vertical-align: baseline; font-family: inherit; font-weight: inherit; outline: 0px; padding: 0px; margin: 0px; border: 0px;"><span style="font-family: &quot;Segoe UI&quot;;">Word, Excel, Powerpoint</span></em></h4><div bis_skin_checked="1" style="vertical-align: baseline; font-family: Quicksand; font-size: 18px; outline: 0px; padding: 0px; margin: 0px; border: 0px; color: rgb(30, 30, 30);"></div><div bis_skin_checked="1" style="vertical-align: baseline; font-family: Quicksand; font-size: 18px; outline: 0px; padding: 0px; margin: 0px; border: 0px; color: rgb(30, 30, 30);"></div><div class="translated-sentence word-text" bis_skin_checked="1" style="vertical-align: baseline; font-family: Quicksand; font-size: 18px; outline: 0px; padding: 0px; margin: 0px; border: 0px; color: rgb(30, 30, 30);"><span style="font-family: &quot;Segoe UI&quot;;">Với tính năng đồng tác giả trong thời gian thực, bạn có thể làm việc với những người khác trong cùng một tài liệu cùng một lúc. Bạn Không cần gửi&nbsp;</span><span style="vertical-align: baseline;